function roleLabel(m) {
  if (!m) return "";
  if (m.role === "superadmin") return "Owner";
  if (m.role === "leader") return m.leaderTitle === "deputy" ? "نائب رئيس القسم" : "رئيس القسم";
  return "عضو";
}
function roleBadgeColor(m) {
  if (!m) return "#6B7280";
  if (m.role === "superadmin") return "#8C3B4A";
  if (m.role === "leader") return "#E89D5A";
  return "#139299";
}

function compressImage(file, maxSize = 1280, quality = 0.85) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const scale = Math.min(1, maxSize / Math.max(img.width, img.height));
        const w = Math.round(img.width * scale), h = Math.round(img.height * scale);
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        canvas.getContext("2d").drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}
function compressAvatar(file) { return compressImage(file, 160, 0.72); }

// رفع فيديو مباشرة بأعلى جودة ممكنة (بدون ضغط، فقط تحويل لملف يمكن تخزينه)
function readVideoFile(file, maxSizeMB = 8) {
  return new Promise((resolve, reject) => {
    if (file.size > maxSizeMB * 1024 * 1024) {
      reject(new Error(`الفيديو أكبر من ${maxSizeMB}MB — يفضّل رفعه على يوتيوب أو درايف واستخدام الرابط بدل الرفع المباشر`));
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => resolve(e.target.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

